export type StaticMessageKey = "accept" | "dismiss" | "emptyReport";
export type DynamicMessageKey = "matchCount" | "range";

export interface MessageCatalog {
  common: Partial<Record<"accept" | "dismiss", string>>;
  report: Partial<Record<"emptyReport", string>>;
  dynamic: {
    matchCount?: (count: number) => string;
    range?: (start: number, end: number) => string;
  };
}

export function renderMessage(catalog: MessageCatalog, key: StaticMessageKey): string;
export function renderMessage(catalog: MessageCatalog, key: "matchCount", count: number): string;
export function renderMessage(catalog: MessageCatalog, key: "range", start: number, end: number): string;
export function renderMessage(catalog: MessageCatalog, key: StaticMessageKey | DynamicMessageKey, ...values: number[]): string {
  if (key === "accept" || key === "dismiss") {
    const value = catalog.common?.[key];
    return typeof value === "string" ? value : key;
  }
  if (key === "emptyReport") {
    const value = catalog.report?.emptyReport;
    return typeof value === "string" ? value : key;
  }
  if (key === "matchCount") {
    const formatter = catalog.dynamic?.matchCount;
    return typeof formatter === "function" ? formatter(values[0]) : key;
  }
  const formatter = catalog.dynamic?.range;
  return typeof formatter === "function" ? formatter(values[1], values[0]) : key;
}

