import { renderMessage } from './solution';
import type { MessageCatalog } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

const catalog: MessageCatalog = {
  common: { accept: 'Accept', dismiss: '' },
  report: { emptyReport: 'No results' },
  dynamic: {
    matchCount: count => `${count} matches`,
    range: (start, end) => `${start}-${end}`
  }
};

assert(renderMessage(catalog, 'accept') === 'Accept', 'common static message');
assert(renderMessage(catalog, 'dismiss') === '', 'empty translation must be preserved');
assert(renderMessage(catalog, 'emptyReport') === 'No results', 'report static message');
assert(renderMessage(catalog, 'matchCount', 0) === '0 matches', 'zero dynamic value');
assert(renderMessage(catalog, 'matchCount', -2) === '-2 matches', 'negative dynamic value');
assert(renderMessage(catalog, 'range', 3, 9) === '3-9', 'range argument order');

let seen: [number, number] | undefined;
const observing: MessageCatalog = {
  common: { accept: 'a', dismiss: 'd' },
  report: { emptyReport: 'e' },
  dynamic: {
    matchCount: value => String(value),
    range: (start, end) => { seen = [start, end]; return ''; }
  }
};
assert(renderMessage(observing, 'range', 8, 2) === '', 'empty dynamic translation');
assert(JSON.stringify(seen) === JSON.stringify([8, 2]), 'range values must retain order');

const malformedStatic = {
  common: { accept: 42, dismiss: 'ok' },
  report: {},
  dynamic: {}
} as unknown as MessageCatalog;
assert(renderMessage(malformedStatic, 'accept') === 'accept', 'malformed static fallback');
assert(renderMessage(malformedStatic, 'emptyReport') === 'emptyReport', 'missing static fallback');
assert(renderMessage(malformedStatic, 'matchCount', 1) === 'matchCount', 'missing dynamic fallback');

const malformedDynamic = {
  common: { accept: 'a', dismiss: 'd' },
  report: { emptyReport: 'e' },
  dynamic: { matchCount: 'not a function', range: null }
} as unknown as MessageCatalog;
assert(renderMessage(malformedDynamic, 'matchCount', 4) === 'matchCount', 'malformed matchCount fallback');
assert(renderMessage(malformedDynamic, 'range', 1, 2) === 'range', 'malformed range fallback');

const missingBranches = {} as MessageCatalog;
assert(renderMessage(missingBranches, 'dismiss') === 'dismiss', 'missing catalog branch fallback');

const before = JSON.stringify(catalog);
renderMessage(catalog, 'range', 1, 2);
assert(JSON.stringify(catalog) === before, 'catalog must not mutate');

